import asyncio
import json
from asyncio import Queue
from threading import Thread
from typing import Optional

from ute_ue.config import abstract_core_logger_wrapper as logger_wrapper

from taf.ue.android.data_transfer.iperf.ueservice.controller import ControllerCommandHandler, DeviceCommandHandler
from taf.ue.android.data_transfer.iperf.ueservice.nats_communicator import NatsCommunicator

# NATS server URL -> NatsCommunicator
nats_communicators: dict[str, NatsCommunicator] = {}
ue_service_nats_communicator: Optional[NatsCommunicator] = None
SENTINEL = object()
DEFAULT_NATS_URL = "nats://127.0.0.1:4222"


class IperfDtNatsThread(Thread):  # pylint: disable=unnecessary-pass
    """Object responsible for managing Android data transfer."""

    # pylint: disable=protected-access, too-many-instance-attributes
    def __init__(self, dt, *vargs, **kwargs):
        """
        Object responsible for managing NATS publish of data transfer for AndroidUe
        :param dt: Data transfer instance
        :param vargs: Variable arguments
        :param kwargs: Keyword arguments
        """
        self.interlock = False
        self.keep_going = False
        self.event_loop = None
        self.type = "IperfDt"
        self.alias = dt.name
        self.dt = dt  # Data transfer instance
        self.logger = logger_wrapper.create_logger(f'thread-UE-service-{self.type}-{self.alias}',
                                                   f'ute_ue.ue_service.{self.type}-{self.alias}.log')
        super().__init__(*vargs, name=f"{self.type}NatsThread-{self.alias}", **kwargs)
        self.logger.debug(f"{self.alias}: creating instance of {self.type}NatsThread-{self.alias}")
        self.log_lines_sent_to_nats = {}
        self.command_handlers = {}
        self.queue = Queue()
        self._nats_url = self.dt.dt_config["robot_kwargs"].get("output_nats_url", DEFAULT_NATS_URL)
        _stream_subjects = self.dt.dt_config["robot_kwargs"].get("output_stream_subjects", "")
        self._stream_subjects = _stream_subjects.split(",") if _stream_subjects else []
        _merge_data = self.dt.dt_config["robot_kwargs"].get("output_merge")
        try:
            self._merge_data = json.loads(_merge_data) if _merge_data else {}
        except (json.JSONDecodeError, TypeError):
            self.logger.warning(f"Failed to parse kwarg merge data (output_merge): {_merge_data}")
            self._merge_data = {}
        self.logger.debug(f"{self.alias}: created instance of {self.type}NatsThread-{self.alias}"
                          f" with nats_url={self._nats_url}, stream_subjects={self._stream_subjects}, "
                          f"merge_data={self._merge_data}")

    def start(self):
        """
        Starts data transfer with parameters defined in dt_definition passed during initialization.
        :return: None
        """
        if not self.interlock:
            self.logger.debug(f'{self.alias}: not allowed UE-service NATS log publish service')
            return None
        self.log_lines_sent_to_nats = {}
        self.keep_going = True
        self.event_loop = asyncio.new_event_loop()
        self.logger.debug(f'{self.alias}: starting data transfer UE-service NATS log publish service')
        super().start()
        return self

    def stop(self, timeout=None):
        """
        Stops already running data transfer.
        :return: None
        """
        self.keep_going = False
        if not self.interlock:
            return None
        self.logger.debug(f'{self.alias}: stopping data transfer UE-service NATS log publish service')
        try:
            self.queue.put_nowait((None, SENTINEL))
            self.join(timeout)
            if self.event_loop and self.event_loop.is_running():
                self.event_loop.call_soon_threadsafe(self._stop_coroutine)
        except Exception as exc:
            self.logger.debug(f'{self.name}: NATS thread stopped with error: {exc}')
        else:
            self.logger.debug(f'{self.name}: NATS thread stopped')

    def run(self):
        """Run thread """
        try:
            self.logger.debug(f"{self.alias} - UeThread run start")
            self.event_loop.run_until_complete(self._run_coroutines())
        except Exception as e:  # pylint: disable=broad-except
            self.logger.debug(f"exception in '_run_nats_messaging', it should never happened, {e}")
        finally:
            self.logger.debug(f"{self.alias} - {self.type}NatsThread-{self.alias} run finish with success")

    async def _run_coroutines(self):
        """Run the coroutines for NATS messaging and updating iperf outputs."""
        await asyncio.gather(
            self._run_nats_messaging(),
            self._update_iperf_outputs(),
        )

    def _stop_coroutine(self):
        """Stop the coroutine and event loop."""
        while not self.queue.empty():
            self.queue.task_done()
        if self.event_loop.is_running():
            self.event_loop.stop()

    async def _run_nats_messaging(self):  # noqa: C901
        """
        Handle NATS messaging for iperf data transfer.

        Manages the NATS communication for the iperf data transfer, sending data lines
        to the appropriate command handlers and ensuring the communication continues
        as long as `keep_going` and `interlock` are True.
        """
        self.logger.debug(f"{self.alias}: iperf - getting NATS ..")
        nats_communicator = await self.get_nats_communicator()
        if not nats_communicator.nc.is_connected:
            self.logger.error(f"Failed to connect to NATS server {self._nats_url}")
            return
        command_id_ue = f"{self.dt.ue_instance.id}_iperf_{self.dt.name}"
        device_id = {
                        "id": self.dt.ue_instance.id,
                        "product": getattr(self.dt.ue_instance, 'ue_product', 'unknown'),
                        "model": getattr(self.dt.ue_instance, 'ue_model', 'unknown'),
                        "imei": getattr(self.dt.ue_instance, 'ue_imei', 'unknown'),
                        "osSwVersion": getattr(self.dt.ue_instance, 'ue_os_version', 'unknown'),
                        "os": "android",
                    }
        command_handler_ue = DeviceCommandHandler(logger=self.logger,
                                                  command_id=command_id_ue,
                                                  device_id=device_id,
                                                  agent_id=self.dt.ue_endpoint.endpoint_access.hostname,
                                                  agent_address=self.dt.ue_endpoint.endpoint_access.hostname,
                                                  nc=nats_communicator,
                                                  merge_data=self._merge_data)
        command_handler_app_server = ControllerCommandHandler(logger=self.logger,
                                                              command_id=command_id_ue,
                                                              nc=nats_communicator,
                                                              merge_data=self._merge_data)
        if self._stream_subjects:
            self.logger.debug(f"Setting stream subjects: {self._stream_subjects}")
            command_handler_ue.output_stream_subjects = self._stream_subjects
            command_handler_app_server.output_stream_subjects = self._stream_subjects
        command_handler_ue.nats_communicator = nats_communicator
        command_handler_app_server.nats_communicator = nats_communicator
        self.command_handlers.update({self.dt.ue_endpoint: command_handler_ue})
        self.command_handlers.update({self.dt.app_server_endpoint: command_handler_app_server})
        self.log_lines_sent_to_nats = {self.dt.ue_endpoint: [], self.dt.app_server_endpoint: []}

        # Handle command output from queue per each endpoint and per each output stream subject
        while self.keep_going and self.interlock:
            try:
                endpoint, new_data_line = await self.queue.get()
                if new_data_line is SENTINEL:  # Trigger close threading.queue
                    break
                command_handler = self.command_handlers[endpoint]
                nc = command_handler.nats_communicator.nc
                if not nc.is_connected:
                    self.logger.warning(f"{command_handler.__class__.__name__}: NATS connection is closed!")
                for output_stream_subject in command_handler.output_stream_subjects:
                    await command_handler.handle_cmd_output(new_data_line, subject=output_stream_subject)
                self.queue.task_done()
            except asyncio.CancelledError:
                break
            await asyncio.sleep(0.01)
        await nats_communicator.nc.close()

    async def _update_iperf_outputs(self):
        """
        Update iperf outputs and add new log lines to the queue.
        Note! Here are put only messages from the iperf server.
        """
        while self.keep_going and self.interlock:
            self.dt._read_iperf_output_and_validate_status(obligatory_check=False)
            for endpoint, command_handler in self.command_handlers.items():
                if endpoint != self.dt.server:
                    continue
                data_lines = self.dt.iperf_output[endpoint]
                command_handler.command = self.get_iperf_command(endpoint)
                for data_line in data_lines:
                    if data_line not in self.log_lines_sent_to_nats[endpoint]:
                        await self.queue.put((endpoint, data_line))
                        self.log_lines_sent_to_nats[endpoint].append(data_line)
            await asyncio.sleep(0.5)

    def get_iperf_command(self, endpoint):
        """
        Format to simplified iperf command.
        """
        sub_commands = str(self.dt.iperf_cmds[endpoint]).split(";")
        if len(sub_commands) < 2:
            return ""
        else:
            formatted_command = (str(sub_commands[1])
                                 .lstrip()
                                 .replace("2>&1", "")
                                 .rstrip())
            return formatted_command

    async def get_nats_communicator(self) -> NatsCommunicator:
        """
        Retrieve or create a NATS communicator for the given NATS URL.

        Checks if a NATS communicator already exists for the specified NATS URL.
        If it does, it returns the existing communicator. If not, it creates
        a new NATS communicator, initializes it, and stores it in the global dictionary
        for future use.

        :return: An instance of NatsCommunicator associated with the specified NATS URL.
        :rtype: NatsCommunicator
        """
        global nats_communicators
        nats_url = self._nats_url
        nats_communicator = nats_communicators.get(nats_url)
        if not nats_communicator:
            self.logger.debug(f"Creating new NatsCommunicator for {nats_url} ..")
            nats_communicator = await self._create_nats_communicator(nats_url)
        elif not nats_communicator.nc.is_connected:
            self.logger.debug(f"Reconnect existing NatsCommunicator for {nats_url}")
            await nats_communicator.create_client_and_connect()
        elif nats_communicator.nc.is_connected:
            self.logger.debug(f"Using already connected NatsCommunicator for {nats_url}")
        nats_communicators.update({nats_url: nats_communicator})
        return nats_communicator

    async def _create_nats_communicator(self, nats_url: str) -> NatsCommunicator:
        nats_communicator = NatsCommunicator(nats_server=nats_url,
                                             logger=self.logger,
                                             ue_service_id=self.dt.name)
        await nats_communicator.create_client_and_connect()
        self.logger.info(f"Initialized NatsCommunicator for {nats_url}")
        return nats_communicator
